SELECT json_build_object('plans',(SELECT json_agg(t) FROM (SELECT execution_id,plan_hash,schema_version,planner_version,status FROM execution_plans WHERE execution_id IN ('5aa9cb73-00ca-4094-8219-d2da3a151de7'::uuid,'01271aa1-c4e8-427d-9d2c-5927193be4b2'::uuid,'3047718d-34f4-4378-bd0a-bdd22d3be1c5'::uuid,'1fe1138e-4577-49fc-b6ba-67d53b2e37d2'::uuid,'1fe1138e-4577-49fc-b6ba-67d53b2e37d2'::uuid,'0fe9b233-12d6-4407-a666-001a6a06be8c'::uuid,'0c89f0a7-8930-4e15-88d5-db87b5bb043e'::uuid,'436e1e03-1629-456b-9bd1-d4906f242a4d'::uuid,'3424c0d5-191b-41ef-ae56-45426a04fb58'::uuid,'ddc5ad9a-33d1-483b-b939-ef43821e0e0d'::uuid,'bae56207-3208-4411-9681-2b42d2a44289'::uuid))t),'calls',(SELECT json_agg(t) FROM (SELECT l.execution_id,l.trace_id,l.purpose,l.provider,l.model_id,l.input_tokens,l.output_tokens,l.cached_tokens,l.created_at,s.generation_params_json,s.input_refs_json,s.catalog_snapshot_digest,s.model_policy_digest FROM llm_usage_ledger l JOIN prompt_snapshots s ON s.id=l.prompt_snapshot_id WHERE l.execution_id IN ('5aa9cb73-00ca-4094-8219-d2da3a151de7'::uuid,'01271aa1-c4e8-427d-9d2c-5927193be4b2'::uuid,'3047718d-34f4-4378-bd0a-bdd22d3be1c5'::uuid,'1fe1138e-4577-49fc-b6ba-67d53b2e37d2'::uuid,'1fe1138e-4577-49fc-b6ba-67d53b2e37d2'::uuid,'0fe9b233-12d6-4407-a666-001a6a06be8c'::uuid,'0c89f0a7-8930-4e15-88d5-db87b5bb043e'::uuid,'436e1e03-1629-456b-9bd1-d4906f242a4d'::uuid,'3424c0d5-191b-41ef-ae56-45426a04fb58'::uuid,'ddc5ad9a-33d1-483b-b939-ef43821e0e0d'::uuid,'bae56207-3208-4411-9681-2b42d2a44289'::uuid) ORDER BY l.created_at)t));